'use strict';
const SPACING={1:[2],2:[1,4],3:[0,2,4],4:[0,1,3,5],5:[0,1,2,4,5],6:[0,1,2,3,4,5],7:[0,1,2,3,4,5,6]};
const ROUTINES=['Push','Pull','Lower','Full Body'];
function isRotation(p=profile()){return p.mode==='rotation';}
function nextWorkoutIndex(p=profile()){return (p.rotationIndex||0)%p.schedule.length;}
function defaultWorkoutIndex(){return isRotation()?nextWorkoutIndex():(new Date().getDay()+6)%7;}
function weeklyTarget(p=profile()){return isRotation(p)?(p.weeklyTarget||3):p.schedule.filter(d=>d.type!=='Rest').length;}
function draftForProfile(){
 const p=profile(),fresh=p.onboardingComplete===false,selected=!isRotation()?p.schedule.map((d,i)=>d.type==='Rest'?-1:i).filter(i=>i>=0):SPACING[weeklyTarget(p)];
 return {mode:p.mode||'rotation',target:weeklyTarget(p),days:selected?.length?selected.slice():SPACING[3].slice(),equipment:p.equipment.slice(),bans:p.bans.slice(),assignments:!isRotation(p)?Object.fromEntries(p.schedule.map((d,i)=>[i,d.type]).filter(([,t])=>ROUTINES.includes(t))):{},experience:p.experience||'intermediate',system:fresh?'auto':p.schedule.filter(d=>d.type!=='Rest').every(d=>d.type==='Full Body')?'full-body':'ppl',step:1,fresh};
}
function openSetup(){if(hasActive()){toast('Finish or reset your active workout before changing setup.');return;}setupDraft=draftForProfile();tab='Setup';focusMode=false;render();}
function planSequence(d=setupDraft){return (d.system==='auto'?d.target<=3:d.system==='full-body')?['Full Body']:['Push','Pull','Lower'];}
function plannedProfile(){
 const d=setupDraft,p={...profile(),mode:d.mode,weeklyTarget:d.target,equipment:d.equipment,bans:d.bans,experience:d.experience},days=d.days.slice().sort((a,b)=>a-b),seq=planSequence(d);
 p.schedule=d.mode==='rotation'?seq.map(type=>({type,custom:null})):DAYS.map((_,i)=>({type:days.includes(i)?(d.assignments[i]||seq[days.indexOf(i)%seq.length]):'Rest',custom:null}));return p;
}
function setupView(){
 setupDraft??=draftForProfile();const d=setupDraft,labels=['Schedule','Equipment','Exclusions','Experience','Your plan'];
 return `<section class="onboarding"><div class="setup-heading"><span class="eyebrow">${d.fresh?'WELCOME TO DAILY REPS':'ADJUST YOUR PLAN'} · ${d.step} / 5</span><h1>${['When will you train?','What can you train with?','What do you want to avoid?','Find your starting point','Your training plan'][d.step-1]}</h1><p class="muted">${d.fresh?'A few choices. A plan that fits you.':'Changes affect upcoming workouts; your history stays saved.'}</p></div><div class="setup-step-track" aria-label="Setup progress">${labels.map((label,i)=>`<span class="${d.step>=i+1?'done':''}" aria-label="${label}" ${d.step===i+1?'aria-current="step"':''}></span>`).join('')}</div><section class="section setup-content">${[daysStep,equipmentStep,exclusionsStep,experienceStep,previewStep][d.step-1]()}</section>${!d.fresh?'<button class="text-button" data-setup="cancel">Cancel changes</button>':''}</section>`;
}
function setupActions(nextLabel='Continue',disabled=false){const d=setupDraft;return `<div class="builder-actions setup-actions">${d.step>1?`<button data-setup="step" data-value="${d.step-1}">Back</button>`:''}<button class="primary" data-setup="step" data-value="${d.step+1}" ${disabled?'disabled':''}>${nextLabel}</button></div>`;}
function daysStep(){const d=setupDraft,n=d.mode==='rotation'?d.target:d.days.length;return `<h2>How often?</h2><p class="small muted">Each workout takes 20 minutes. Choose a goal you can repeat.</p><div class="day-count">${[1,2,3,4,5,6,7].map(i=>`<button data-setup="count" data-value="${i}" aria-label="${i} sessions per week" aria-pressed="${n===i}" class="${n===i?'selected':''}">${i}</button>`).join('')}</div><div class="focus-options">${[['rotation','Flexible days','Continue with the next workout whenever you train.'],['fixed','Fixed weekdays','Choose your training days.']].map(([v,name,desc])=>`<button data-setup="mode" data-value="${v}" class="${d.mode===v?'selected':''}" aria-pressed="${d.mode===v}"><strong>${name}</strong><span>${desc}</span></button>`).join('')}</div>${d.mode==='fixed'?`<div class="chips">${DAYS.map((name,i)=>`<button data-setup="day" data-value="${i}" class="chip ${d.days.includes(i)?'selected':''}" aria-pressed="${d.days.includes(i)}">${name.slice(0,3)}</button>`).join('')}</div>`:''}<label for="setup-system">Training structure</label><select id="setup-system" data-setup-system><option value="auto" ${d.system==='auto'?'selected':''}>Recommend for my frequency</option><option value="full-body" ${d.system==='full-body'?'selected':''}>Full body</option><option value="ppl" ${d.system==='ppl'?'selected':''}>Push / Pull / Lower</option></select><p class="small muted setup-explanation">${planSequence().length===1?'Full body: train legs, chest, back and core each session. Recommended for 1–3 sessions a week.':'Push / Pull / Lower: spread muscle groups over a rotation. Plan regular sessions so each group gets its turn.'}</p>${setupActions('Choose equipment',!n)}`;}
function equipmentStep(){const d=setupDraft,codes=['DB','KB','SB','RB','BB','BW','PL','AW','SUP','RACK'];return `<p class="small muted">Only select equipment you actually have. Bodyweight needs no weights; a bench or rack is a separate requirement.</p><div class="equipment-grid">${EQUIPMENT.map((e,i)=>`<button data-setup="equipment" data-value="${e}" class="equipment-tile ${d.equipment.includes(e)?'selected':''}" aria-pressed="${d.equipment.includes(e)}"><span class="equipment-code">${codes[i]}</span><strong>${e}</strong><span class="tile-check">${d.equipment.includes(e)?'✓':'+'}</span></button>`).join('')}</div>${setupActions('Choose exclusions',!d.equipment.length)}`;}
function exclusionsStep(){const d=setupDraft;return `<h2>Exercises you prefer to skip</h2><p class="small muted">Optional. Exclude a specific exercise or a category. This is a preference filter, not an injury assessment.</p><div class="chips">${[...new Set(['Lunge','Jump','Overhead Press','Barbell Squat','Bench Press',...d.bans])].map(v=>`<button data-setup="ban" data-value="${esc(v)}" class="chip ${d.bans.includes(v)?'selected':''}" aria-pressed="${d.bans.includes(v)}">${d.bans.includes(v)?'✓ ': '+ '}${esc(v)}</button>`).join('')}</div><form id="setup-ban-form" class="inline-form"><label class="sr-only" for="setup-ban">Exercise or category to exclude</label><input id="setup-ban" name="ban" list="exclude-exercises" placeholder="Search an exercise or type a category" maxlength="80" required><datalist id="exclude-exercises">${Object.values(MOVES).filter(m=>!m.libraryAlias).map(m=>`<option value="${esc(m.name)}">${esc(groupLabel(m))}</option>`).join('')}${Object.values(MUSCLE_GROUPS).map(g=>`<option value="${esc(g)}"></option>`).join('')}</datalist><button>Add</button></form><p class="small muted">Nothing to exclude? Continue without selecting anything.</p>${setupActions('Choose starting level')}`;}
function experienceStep(){const d=setupDraft;return `<p class="small muted">This selects reference challenge levels, not a fitness test. You can change every exercise before or during a workout.</p><div class="experience-options">${[['beginner','New or returning','Start with simpler variants and build consistency.'],['intermediate','Regular training','Familiar movements with moderate challenge.'],['advanced','Experienced','More demanding variants where your equipment allows.']].map(([v,title,desc])=>`<button data-setup="experience" data-value="${v}" class="${d.experience===v?'selected':''}" aria-pressed="${d.experience===v}"><strong>${title}</strong><span>${desc}</span></button>`).join('')}</div>${setupActions('Preview my plan')}`;}
function previewStep(){const p=plannedProfile(),d=setupDraft,n=d.mode==='rotation'?d.target:d.days.length,blocked=p.schedule.some((plan,i)=>plan.type!=='Rest'&&circuit(i,p).some(r=>!r.main));return `<h2>${planSequence().length===1?'Full body':'Push / Pull / Lower'}</h2><p>${n} sessions per week · ${n*20} minutes</p><p class="small muted">${d.mode==='rotation'?'Flexible days: continue where you left off.':'Fixed days: '+d.days.slice().sort((a,b)=>a-b).map(i=>DAYS[i]).join(', ')} · ${esc(d.experience)} starting point.</p><div class="plan-preview">${p.schedule.map((plan,i)=>plan.type==='Rest'?'':`<details ${i===0?'open':''}><summary><span>${d.mode==='rotation'?`Workout ${i+1}`:DAYS[i]}</span><strong>${plan.type}</strong><small>5 exercises · 20 min</small></summary><ol>${circuit(i,p).map(r=>`<li><strong>${esc(r.main?.name||'No matching exercise')}</strong><small>${r.main?esc(groupLabel(r.main))+' · '+challengeBadge(r.main):'Adjust equipment or exclusions'}</small></li>`).join('')}</ol></details>`).join('')}</div>${blocked?'<div class="alert">Your filters leave empty slots. Go back and adjust your equipment or exclusions.</div>':''}<p class="small muted">Your history stays saved. This replaces your upcoming custom routines and resets the rotation. You can change any exercise later.</p><div class="builder-actions setup-actions"><button data-setup="step" data-value="4">Back</button><button class="primary" data-setup="apply" ${blocked||!n?'disabled':''}>${d.fresh?'Use plan & open first workout':'Save my plan'}</button></div>`;}
function applySetup(){
 if(hasActive()||!setupDraft)return;const draft=plannedProfile();if(!draft.schedule.some(d=>d.type!=='Rest')||draft.schedule.some((d,i)=>d.type!=='Rest'&&circuit(i,draft).some(r=>!r.main))){toast('Adjust your filters to fill all five slots.');return;}
 const p=profile();p.previousPlan={schedule:clone(p.schedule),mode:p.mode,equipment:clone(p.equipment),bans:clone(p.bans),experience:p.experience,setup:clone(p.setup||null)};
 p.schedule=clone(draft.schedule);p.mode=draft.mode;p.weeklyTarget=draft.mode==='rotation'?setupDraft.target:setupDraft.days.length;p.rotationIndex=0;p.equipment=[...draft.equipment];p.bans=[...draft.bans];p.experience=draft.experience;p.onboardingComplete=true;p.setup={mode:p.mode,days:setupDraft.days.slice(),updatedAt:Date.now()};p.workoutOverrides=null;p.session=null;previewSwaps={};day=defaultWorkoutIndex();tab='Workout';setupDraft=null;persist();render();toast('Your plan is ready.');
}

function weekGoal(){const p=profile(),goal=weeklyTarget(),d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);const from=localDate(d);d.setDate(d.getDate()+7);const to=localDate(d),count=p.history.filter(h=>h.date>=from&&h.date<to).length;return `<div class="week-goal"><div><span class="eyebrow">THIS WEEK · ${isRotation()?'ROLLING':'FIXED'}</span><strong>${count}<span> / ${goal} sessions</span></strong></div><div class="week-goal-track" role="progressbar" aria-label="Weekly training goal" aria-valuemin="0" aria-valuemax="${Math.max(goal,1)}" aria-valuenow="${Math.min(count,Math.max(goal,1))}"><i style="width:${goal?Math.min(100,count/goal*100):0}%"></i></div><button class="small" data-action="setup">Adjust plan</button></div>`;}
function circuitFingerprint(rows){return JSON.stringify(rows.map(r=>r.main?{name:r.main.name,equipment:[...r.main.equipment].sort(),reps:r.main.reps,description:r.main.description,weightKg:r.main.weightKg??savedLoad(r.main)}:null));}
function echoMatch(rows){const fingerprint=circuitFingerprint(rows);return profile().history.slice().reverse().find(h=>h.fingerprint===fingerprint&&h.echoEligible&&h.repLog?.some(e=>Number.isFinite(e.at)&&e.at<=1200000&&e.unit==='reps'));}
function echoPanel(s,rows){if(s?.overtime)return '<div class="echo-panel"><strong>20-minute comparison finished</strong><p>Overtime entries stay in your workout totals. Echo compares only rep entries logged in the first 20 minutes.</p></div>';const match=s&&!s.echoInvalid?profile().history.slice().reverse().find(h=>h.fingerprint===s.fingerprint&&h.echoEligible&&h.repLog?.some(e=>Number.isFinite(e.at)&&e.at<=1200000&&e.unit==='reps')):s?null:echoMatch(rows);return `<div class="echo-panel"><div class="echo-heading"><span class="eyebrow">ECHO / PREVIOUS WORKOUT</span><button data-action="echo-toggle" aria-pressed="${!profile().echoOff}">${profile().echoOff?'Off':'On'}</button></div>${profile().echoOff?'<p>Comparison is off.</p>':s?.echoInvalid?'<p>Movement or load changed. Echo is off for this session so different circuits are not compared.</p>':match?`<strong id="echo-delta">${s?'Comparing rep counts':'Previous workout available'}</strong><div class="echo-tracks"><label>YOU <span id="echo-you">0</span></label><div><i id="echo-you-bar"></i></div><label>PREVIOUS <span id="echo-previous">0</span></label><div><i id="echo-previous-bar"></i></div></div><p>Compared at the same elapsed time · ${new Date(match.finishedAt).toLocaleDateString()}. Matched by exercises and recorded load. Rep pace only, not a strength score.</p>`:'<strong>No matching workout yet.</strong><p>Complete this circuit to record your rep timing. Echo compares it with your next session using the same exercises and recorded loads.</p>'}</div>`;}
function updateEcho(){const s=activeSession();if(!s||s.finished||s.overtime||s.day!==day||s.echoInvalid||profile().echoOff)return;const el=document.querySelector('#echo-delta');if(!el)return;const match=profile().history.slice().reverse().find(h=>h.fingerprint===s.fingerprint&&h.echoEligible&&h.repLog?.some(e=>Number.isFinite(e.at)&&e.at<=1200000&&e.unit==='reps'));if(!match)return;const elapsed=Math.min(1200000,workoutElapsed(s)),previous=match.repLog.filter(e=>e.unit==='reps'&&e.at<=elapsed).reduce((n,e)=>n+e.amount,0),now=countTotal(repEntries(s)),diff=now-previous,max=Math.max(1,now,previous,match.repLog.filter(e=>e.unit==='reps'&&e.at<=1200000).reduce((n,e)=>n+e.amount,0));el.textContent=diff===0?'Same rep count as last time':`${Math.abs(diff)} reps ${diff>0?'ahead of':'behind'} your previous pace`;document.querySelector('#echo-you').textContent=now;document.querySelector('#echo-previous').textContent=previous;document.querySelector('#echo-you-bar').style.width=now/max*100+'%';document.querySelector('#echo-previous-bar').style.width=previous/max*100+'%';}

document.addEventListener('click',e=>{
 const b=e.target.closest('[data-setup]');if(!b||b.disabled||!setupDraft)return;const a=b.dataset.setup,v=b.dataset.value,d=setupDraft;
 if(a==='cancel'){setupDraft=null;tab='Workout';render();return;}
 if(a==='step'){const next=Number(v);if(!Number.isInteger(next)||next<1||next>5)return;if(next>2&&!d.equipment.length){toast('Select at least one equipment option.');return;}d.step=next;}
 if(a==='equipment')d.equipment=d.equipment.includes(v)?d.equipment.filter(x=>x!==v):[...d.equipment,v];
 if(a==='ban')d.bans=d.bans.includes(v)?d.bans.filter(x=>x!==v):[...d.bans,v];
 if(a==='mode')d.mode=v;
 if(a==='count'){d.target=Number(v);d.days=SPACING[d.target].slice();d.assignments={};}
 if(a==='day'){const i=Number(v);d.days=d.days.includes(i)?d.days.filter(x=>x!==i):[...d.days,i];d.target=d.days.length;d.assignments={};}
 if(a==='experience')d.experience=v;
 if(a==='apply'){applySetup();window.scrollTo?.(0,0);return;}
 render();if(a==='step')window.scrollTo?.(0,0);
});
document.addEventListener('change',e=>{if(e.target.hasAttribute?.('data-setup-system')&&setupDraft){setupDraft.system=e.target.value;setupDraft.assignments={};render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='setup-ban-form'||!setupDraft)return;e.preventDefault();const value=new FormData(e.target).get('ban').trim();if(norm(value).replace(/^no /,'').length<2){toast('Enter a movement name.');return;}if(!setupDraft.bans.includes(value))setupDraft.bans.push(value);render();});
